//go:build amd64

package floats

// The AVX2+FMA kernels of the windowed overlap-add (overlap.go), generated by
// go-asmgen (overlap_amd64_gen.go) into overlap_amd64.s: eight float32 or four
// float64 lanes per step, for a CPU with the AVX2+FMA of the other kernels
// (hasAVX2FMA, kernels_amd64.go); the portable loop otherwise. A kernel does the
// blocks that fit, (n/lanes)*lanes elements of the n = len(a) steps, and the Go
// code below finishes the tail. No kernel keeps a pointer: go:noescape.
//
//go:noescape
func overlapWindow32AVX2(dst, a, b, win []float32)

//go:noescape
func overlapWindow64AVX2(dst, a, b, win []float64)

func overlapWindow32(dst, a, b, win []float32) {
	if !hasAVX2FMA {
		overlapRef32(dst, a, b, win)
		return
	}
	overlapWindow32AVX2(dst, a, b, win)
	overlapTail32(dst, a, b, win, len(a)&^7)
}

func overlapWindow64(dst, a, b, win []float64) {
	if !hasAVX2FMA {
		overlapRef64(dst, a, b, win)
		return
	}
	overlapWindow64AVX2(dst, a, b, win)
	overlapTail64(dst, a, b, win, len(a)&^3)
}
